import heapq

def k_closest(nums, k, target):
    heap = []
    for num in nums:
        dist = abs(num - target)
        if len(heap) < k:
            heapq.heappush(heap, (-dist, num))
        elif dist < -heap[0][0]:
            heapq.heappushpop(heap, (-dist, num))

    result = [pair[1] for pair in heap]
    result.sort()
    return result
